(() => {'use strict';const g=()=>window.gameDebug,$=id=>document.getElementById(id);
function locked(item){const a=g().active();if(item.guard&&!item.guard())return 'Рюкзак изменился. Выберите предмет заново.';if(a.dead||a.hp<=0)return 'Герой без сознания и не может распоряжаться вещами.';if(g().busy||window.HUD?.pending||g().state.combat)return 'Дождитесь окончания движения или боя.';if(item.id.startsWith('gear')){const entry=InventoryRules.gearEntries(a).find(it=>it.id===item.id),name=a.inventory[+item.id.slice(4)]||'';if(!entry||item.rawName&&item.rawName!==name)return 'Предмет больше недоступен.';if(InventoryRules.armorName(name)&&entry.equipped)return 'Сначала снимите броню.';const hand=InventoryRules.handType(name);if(hand&&entry.equipped)return 'Сначала уберите этот предмет из рук.';return '';}if(item.id==='torch'){if(!a.torches)return 'Нет факелов.';if(a.hands.includes('torch')&&a.torches===1)return 'Сначала погасите и уберите факел.';return '';}if(item.id==='potion'){const state=g().state;if(state.potions===1&&state.tutorial&&!state.tutorial.completed&&!state.tutorial.checks.potion)return 'Оставьте последнее зелье: оно понадобится в обязательном шаге обучения.';return state.potions>0?'':'Нет зелий.';}return 'Этот предмет связан с историей или не передаётся.';}
function protectedItem(item){
 const state=g().state,actor=g().active(),contents=JSON.stringify(actor.inventory),torches=actor.torches,potions=state.potions;
 return {...item,guard:()=> (!item.guard||item.guard())&&g().state===state&&g().active()===actor&&JSON.stringify(actor.inventory)===contents&&actor.torches===torches&&state.potions===potions};
}
function confirmAction(item,title,explanation,action){
 const safe=protectedItem(item),d=$('modal'),body=$('modal-body');$('modal-title').textContent=title;body.replaceChildren();
 const text=document.createElement('p');text.textContent=explanation;body.append(text);
 const cancel=document.createElement('button');cancel.textContent='Отмена';cancel.onclick=()=>d.close();
 const ok=document.createElement('button');ok.textContent=title;ok.onclick=()=>{const reason=locked(safe);d.close();if(reason){g().tell(reason);g().render();return;}action(safe);};body.append(cancel,ok);d.showModal();cancel.focus();
}
function take(item){if(locked(item))return null;const a=g().active();if(item.id.startsWith('gear')){const index=+item.id.slice(4);const name=a.inventory.splice(index,1)[0];return name?{name,itemType:'gear'}:null;}if(item.id==='torch'){a.torches--;return{name:'Факел',itemType:'torch'};}if(item.id==='potion'){g().state.potions--;return{name:'Лечебное зелье',itemType:'potion'};}return null;}
function drop(item){const reason=locked(item);if(reason){g().tell(reason);g().render();return;}if((g().state.drops||[]).length>=100){g().tell("Сначала подберите оставленные вещи.");g().render();return;}const a=g().active(),S=g().scene,candidates=[];for(let y=Math.max(0,a.y-2);y<=Math.min(S.H-1,a.y+2);y++)for(let x=Math.max(0,a.x-2);x<=Math.min(S.W-1,a.x+2);x++){const distance=Math.abs(x-a.x)+Math.abs(y-a.y);if(distance<=2&&!g().blocked({x,y})&&!g().props.some(p=>p.x===x&&p.y===y)&&!g().all().some(p=>p.x===x&&p.y===y))candidates.push({x,y,distance});}candidates.sort((a,b)=>a.distance-b.distance||a.y-b.y||a.x-b.x);if(!candidates.length){g().tell('Рядом нет свободной клетки для вещи.');g().render();return;}const dropId='drop-'+window.LocalAPI.randomUUID();const data=take(item);if(!data)return;g().state.drops||=[];g().state.drops.push({...data,id:dropId,scene:S.id,x:candidates[0].x,y:candidates[0].y});g().tell('Вы оставили «'+data.name+'» на полу. Вещь можно подобрать обратно.');g().save();g().render();}
function roomFor(type,name){return InventoryRules.canAdd(g().active(),g().state,type,name);}
function pickup(p){const drops=g().state.drops||[],i=drops.findIndex(d=>d.id===p.id);if(i<0)return;const d=drops[i];if(!roomFor(d.itemType,d.name)){window.openObjectDialogue({name:'Рюкзак заполнен',description:'Все 20 ячеек заняты. Освободите место или передайте вещь NPC. Предмет остался на полу.'});g().render();return;}if(d.itemType==='gear')g().active().inventory.push(d.name);else if(d.itemType==='torch')g().active().torches++;else if(d.itemType==='potion')g().state.potions++;drops.splice(i,1);window.dispatchEvent(new CustomEvent('game-action',{detail:{type:'loot',success:true,propId:p.id}}));g().tell('Подобрано: '+d.name+'.');g().save();g().render();}
function transfer(item){if(locked(item))return;item=protectedItem(item);const d=$('modal'),body=$('modal-body');$('modal-title').textContent='Передать предмет';body.replaceChildren();const npcs=g().props.filter(p=>p.type==='npc');if(!npcs.length){body.textContent='В этой комнате нет NPC. Подойдите в комнату с персонажем.';}for(const npc of npcs){const b=document.createElement('button');b.className='npc-transfer';const portrait=npc.npc?Characters.portrait(5,{gen:npc.npc}):window.Artwork.npc(npc.name);const text=document.createElement('span');text.textContent=npc.name;b.append(portrait,text);b.onclick=()=>{d.close();confirmAction(item,'Передать '+npc.name,'Передать «'+(item.name||'предмет')+'» (1 шт.)? Вернуть подарок через рюкзак нельзя.',async safe=>{item=safe;window.viewsDebug.switchTab('map');const ok=await g().approachTransfer(npc,()=>{const data=take(item);if(!data){g().tell(locked(item)||'Передача отменена: предмет недоступен.');return;}g().state.npcGifts||=[];g().state.npcGifts.push(npc.id+': '+data.name);if(g().state.npcGifts.length>200)g().state.npcGifts.shift();g().tell('Вы передали «'+data.name+'» персонажу '+npc.name+'.');window.episodeDialogue('Спасибо, я сохраню эту вещь.',[{label:'Вернуться к карте',fn:window.closeDialogue}],npc.name,true);});if(!ok){g().tell('Передача отменена: нет свободного прохода или движение остановлено.');g().render();}});};body.append(b);}d.showModal();}
function unequip(item){const a=g().active();if(g().busy||g().state.combat||window.HUD?.pending||a.hp<=0||a.dead)return;const name=a.inventory[+item.id.slice(4)];if(!name)return;const copy={...a,hands:[...a.hands],inventory:[...a.inventory]};if(InventoryRules.armorName(name))copy.armorEquipped=false;else{const hand=item.id==='torch'?'torch':InventoryRules.handType(name);copy.hands=copy.hands.map(h=>h===hand?'empty':h);}if(InventoryRules.slotsUsed(copy,g().state)>20){window.openObjectDialogue({name:'Нет места для снаряжения',description:'Освободите ячейку в рюкзаке, чтобы снять этот предмет.'});return;}if(InventoryRules.armorName(name)){a.armorEquipped=false;a.armorAC=10+DND.mod(a.stats.dex);}else{a.hands=copy.hands;if(!a.hands.includes('torch'))a.torch=false;}window.Torches.ensure();a.baseAC=a.ac;window.dispatchEvent(new CustomEvent('game-action',{detail:{type:'equipment',success:true,kind:'armor-or-hands'}}));g().save();g().render();}
function wear(item){const a=g().active(),name=a.inventory[+item.id.slice(4)];if(g().busy||g().state.combat||window.HUD?.pending||a.hp<=0||a.dead||!InventoryRules.armorName(name))return;const kit=HeroRules.CLASSES[a.classId]?.kits[a.kit];if(!kit)return;a.armorEquipped=true;a.armorAC=kit.ac+(a.classId==='fighter'?0:a.classId==='cleric'?Math.min(2,DND.mod(a.stats.dex)):DND.mod(a.stats.dex));window.Torches.ensure();a.baseAC=a.ac;window.dispatchEvent(new CustomEvent('game-action',{detail:{type:'equipment',success:true,kind:'armor-or-hands'}}));g().save();g().render();}
function controls(item,host){
 if(!item.id.startsWith('gear')&&!['torch','potion'].includes(item.id))return;
 const reason=locked(item),a=g().active(),entry=InventoryRules.gearEntries(a).find(it=>it.id===item.id),name=entry?.name||'';
 if(entry&&(entry.equipped||InventoryRules.armorName(name)&&a.armorEquipped===false)){
  const b=document.createElement('button');b.textContent=InventoryRules.armorName(name)&&!entry.equipped?'Надеть броню':'Снять в рюкзак';
  b.onclick=()=>InventoryRules.armorName(name)&&!entry.equipped?wear(item):unequip(item);b.disabled=g().busy||g().state.combat||!!window.HUD?.pending||a.hp<=0||!!a.dead;window.UIIcons.apply(b,'armor');host.append(b);
 }
 if(entry&&InventoryRules.handType(name)){const b=document.createElement('button');b.textContent='Снаряжение рук';b.onclick=()=>window.Torches.openHands();b.disabled=g().busy||g().state.combat||!!window.HUD?.pending||a.hp<=0||!!a.dead;host.append(b);}
 for(const [text,fn,icon]of [['Выбросить',()=>confirmAction(item,'Выбросить','Оставить «'+(item.name||name)+'» (1 шт.) на земле рядом с героем? Его можно будет подобрать.',safe=>drop(safe)),'drop'],['Передать NPC',()=>transfer(item),'transfer']]){
  const b=document.createElement('button');b.className='inventory-action';b.textContent=text;b.disabled=!!reason;b.onclick=fn;window.UIIcons.apply(b,icon);host.append(b);
 }
 if(reason){const p=document.createElement('p');p.className='item-lock-note';p.textContent=reason;host.append(p);}
}

window.Inventory={drop,pickup,transfer,controls,locked,unequip,wear,roomFor};})();
